[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --blue:#3861FB;--blue-light:#EBF0FF;--navy:#0D1421;--gray:#808A9D;
  --gray-light:#EFF2F5;--gray-lighter:#F8FAFD;--white:#FFFFFF;
  --green:#16C784;--green-bg:#E8FBF1;--red:#EA3943;--red-bg:#FDEDED;
  --border:#EFF2F5;--shadow:0 1px 2px rgba(13,20,33,0.06);
  --radius:8px;--radius-sm:6px;
  --font:'Inter',system-ui,-apple-system,sans-serif;
}
html{font-size:14px;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}
body{font-family:var(--font);color:var(--navy);background:var(--gray-lighter);line-height:1.5}
a{color:var(--blue);text-decoration:none}
a:hover{text-decoration:underline}
button{font-family:inherit;cursor:pointer;border:none;background:none}
img{display:block;max-width:100%}

/* HEADER / NAV */
.header{background:var(--white);border-bottom:1px solid var(--border);position:sticky;top:0;z-index:100}
.header-inner{max-width:1400px;margin:0 auto;padding:0 20px;display:flex;align-items:center;height:56px;gap:24px}
.logo{font-weight:800;font-size:18px;color:var(--navy);display:flex;align-items:center;gap:8px;white-space:nowrap}
.logo-icon{width:28px;height:28px;background:var(--blue);border-radius:6px;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800;font-size:14px}
.nav{display:flex;gap:4px;flex:1}
.nav-item{position:relative;padding:8px 14px;font-size:13px;font-weight:500;color:var(--navy);border-radius:var(--radius-sm);transition:background .15s}
.nav-item:hover{background:var(--gray-light);text-decoration:none}
.nav-item.active{color:var(--blue)}
.nav-sub{font-size:11px;color:var(--gray);display:none}
.header-actions{display:flex;gap:8px;align-items:center;margin-left:auto}
.btn{padding:8px 16px;border-radius:var(--radius-sm);font-size:13px;font-weight:600;transition:all .15s}
.btn-ghost{color:var(--navy);background:transparent}.btn-ghost:hover{background:var(--gray-light)}
.btn-primary{background:var(--blue);color:#fff}.btn-primary:hover{opacity:.9}
.btn-outline{border:1px solid var(--border);color:var(--navy);background:var(--white)}.btn-outline:hover{border-color:var(--gray)}

/* TOP BAR METRICS */
.metrics-bar{background:var(--white);border-bottom:1px solid var(--border);overflow-x:auto}
.metrics-inner{max-width:1400px;margin:0 auto;padding:10px 20px;display:flex;gap:28px;align-items:center;font-size:12px;white-space:nowrap}
.metric{display:flex;align-items:center;gap:6px}
.metric-label{color:var(--gray);font-weight:500}
.metric-value{font-weight:600;font-variant-numeric:tabular-nums}
.metric-change{font-weight:600;font-variant-numeric:tabular-nums}
.metric-change.up{color:var(--green)}.metric-change.down{color:var(--red)}
.metric-badge{display:inline-flex;align-items:center;gap:4px;padding:2px 8px;border-radius:4px;font-size:11px;font-weight:600}
.badge-neutral{background:#FFF3E0;color:#E65100}
.badge-btc{background:var(--blue-light);color:var(--blue)}
.fear-bar{width:48px;height:6px;background:var(--gray-light);border-radius:3px;overflow:hidden;display:inline-block;vertical-align:middle}
.fear-fill{height:100%;border-radius:3px;background:linear-gradient(90deg,var(--red),#f5a623,var(--green))}

/* PROMO BANNER */
.promo-banner{background:linear-gradient(135deg,#1a2332 0%,#0f3460 50%,#16213e 100%);overflow:hidden;position:relative}
.promo-inner{max-width:1400px;margin:0 auto;padding:0 20px;position:relative;height:48px}
.promo-slides{display:flex;transition:transform .5s ease}
.promo-slide{min-width:100%;display:flex;align-items:center;justify-content:center;height:48px;gap:10px;color:#fff;font-size:13px;font-weight:500}
.promo-slide a{color:#64B5F6;font-weight:600}
.promo-dot{width:6px;height:6px;border-radius:50%;background:rgba(255,255,255,.3);display:inline-block;margin:0 3px;cursor:pointer;transition:background .2s}
.promo-dot.active{background:#fff}
.promo-dots{position:absolute;bottom:6px;left:50%;transform:translateX(-50%);display:flex;gap:2px}
.promo-arrow{position:absolute;top:50%;transform:translateY(-50%);background:rgba(255,255,255,.1);border:none;color:#fff;width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:14px;cursor:pointer;transition:background .2s;z-index:2}
.promo-arrow:hover{background:rgba(255,255,255,.2)}
.promo-arrow.prev{left:20px}
.promo-arrow.next{right:20px}

/* AI ALERTS */
.ai-bar{background:var(--white);border-bottom:1px solid var(--border)}
.ai-inner{max-width:1400px;margin:0 auto;padding:12px 20px}
.ai-topic{display:flex;align-items:center;gap:8px;margin-bottom:10px;font-size:13px}
.ai-icon{width:24px;height:24px;background:linear-gradient(135deg,#7C3AED,#3861FB);border-radius:6px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:12px;font-weight:700}
.ai-suggestions{display:flex;gap:8px;overflow-x:auto;padding-bottom:2px}
.ai-chip{padding:6px 14px;background:var(--gray-lighter);border:1px solid var(--border);border-radius:20px;font-size:12px;color:var(--navy);white-space:nowrap;cursor:pointer;transition:all .15s}
.ai-chip:hover{border-color:var(--blue);color:var(--blue);background:var(--blue-light)}

/* MAIN CONTENT */
.main{max-width:1400px;margin:0 auto;padding:20px}

/* TABS */
.tabs-section{margin-bottom:16px}
.tabs-row{display:flex;gap:4px;margin-bottom:8px;flex-wrap:wrap}
.tab{padding:7px 16px;border-radius:var(--radius);font-size:13px;font-weight:500;color:var(--gray);cursor:pointer;transition:all .15s;border:1px solid transparent;user-select:none}
.tab:hover{color:var(--navy);background:var(--gray-light)}
.tab.active{color:var(--blue);background:var(--blue-light);border-color:transparent;font-weight:600}
.network-tabs{display:flex;gap:4px;flex-wrap:wrap}
.network-tab{padding:6px 14px;border-radius:20px;font-size:12px;font-weight:500;color:var(--gray);cursor:pointer;border:1px solid var(--border);transition:all .15s;user-select:none}
.network-tab:hover{color:var(--navy);border-color:var(--gray)}
.network-tab.active{color:var(--blue);background:var(--blue-light);border-color:var(--blue)}

/* INDEX TRACKER */
.index-row{background:var(--white);border:1px solid var(--border);border-radius:var(--radius);padding:12px 20px;margin-bottom:16px;display:flex;align-items:center;gap:24px;font-size:13px}
.index-name{font-weight:600;color:var(--navy);white-space:nowrap}
.index-ticker{color:var(--gray);font-weight:500;font-size:12px}
.index-price{font-weight:700;font-variant-numeric:tabular-nums}
.index-changes{display:flex;gap:16px}
.index-change{font-weight:600;font-variant-numeric:tabular-nums;font-size:12px}

/* TABLE CONTROLS */
.table-controls{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;flex-wrap:wrap;gap:8px}
.table-controls-left{display:flex;gap:8px;align-items:center}
.table-controls-right{display:flex;gap:8px;align-items:center}
.control-btn{display:flex;align-items:center;gap:6px;padding:7px 14px;border-radius:var(--radius-sm);font-size:12px;font-weight:500;color:var(--navy);border:1px solid var(--border);background:var(--white);transition:all .15s}
.control-btn:hover{border-color:var(--gray);background:var(--gray-lighter)}
.control-btn.active{border-color:var(--blue);color:var(--blue);background:var(--blue-light)}
.control-btn svg{width:14px;height:14px}
.sort-dropdown{padding:7px 14px;border-radius:var(--radius-sm);font-size:12px;font-weight:600;color:var(--navy);border:1px solid var(--border);background:var(--white);cursor:pointer}

/* DROPDOWN PANELS */
.panel-overlay{display:none;position:fixed;inset:0;z-index:50}
.dropdown-panel{display:none;position:absolute;top:100%;left:0;margin-top:4px;background:var(--white);border:1px solid var(--border);border-radius:var(--radius);box-shadow:0 8px 24px rgba(13,20,33,.12);padding:16px;z-index:60;min-width:280px}
.dropdown-panel.open{display:block}
.panel-title{font-size:13px;font-weight:600;margin-bottom:12px}
.panel-option{display:flex;align-items:center;gap:8px;padding:6px 0;font-size:13px;cursor:pointer}
.panel-option input[type="checkbox"]{accent-color:var(--blue);width:16px;height:16px}
.filter-group{margin-bottom:12px}
.filter-label{font-size:11px;font-weight:600;color:var(--gray);text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px}
.filter-range{display:flex;gap:8px;align-items:center}
.filter-input{width:100%;padding:6px 10px;border:1px solid var(--border);border-radius:var(--radius-sm);font-size:12px;font-family:var(--font)}

/* TABLE */
.table-wrapper{background:var(--white);border-radius:var(--radius);border:1px solid var(--border);overflow-x:auto}
table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}
thead{position:sticky;top:0;z-index:10}
thead th{background:var(--white);padding:12px 14px;font-size:11px;font-weight:600;color:var(--gray);text-transform:uppercase;letter-spacing:.3px;border-bottom:2px solid var(--border);white-space:nowrap;cursor:pointer;user-select:none;transition:color .15s}
thead th:hover{color:var(--navy)}
thead th.num{text-align:right}
thead th.center{text-align:center}
thead th:first-child{padding-left:20px}
thead th:last-child{padding-right:20px}
tbody tr{border-bottom:1px solid var(--border);transition:background .1s}
tbody tr:hover{background:var(--gray-lighter)}
tbody tr:last-child{border-bottom:none}
td{padding:10px 14px;font-size:13px;white-space:nowrap}
td:first-child{padding-left:20px}
td:last-child{padding-right:20px}
td.rank{color:var(--gray);font-weight:500;width:40px}
td.num{text-align:right;font-weight:500}
td.pct{text-align:right;font-weight:600;font-size:12px}
td.pct.up{color:var(--green)}
td.pct.down{color:var(--red)}
.coin-info{display:flex;align-items:center;gap:10px}
.coin-logo{width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:11px;color:#fff;flex-shrink:0}
.coin-name{font-weight:600;font-size:13px}
.coin-ticker{color:var(--gray);font-size:12px;font-weight:500;margin-left:6px}
.sparkline{width:120px;height:40px}
.sparkline svg{width:100%;height:100%}
td.star-col{width:30px;text-align:center;color:var(--gray);cursor:pointer;font-size:16px}
td.star-col:hover{color:#f5a623}
td.star-col.starred{color:#f5a623}

/* COLUMN VISIBILITY */
.col-hidden{display:none}

/* PAGINATION */
.pagination{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;flex-wrap:wrap;gap:8px}
.pagination-info{font-size:12px;color:var(--gray)}
.pagination-pages{display:flex;gap:4px;align-items:center}
.page-btn{min-width:32px;height:32px;display:flex;align-items:center;justify-content:center;border-radius:var(--radius-sm);font-size:13px;font-weight:500;color:var(--navy);border:1px solid var(--border);background:var(--white);cursor:pointer;transition:all .15s}
.page-btn:hover{border-color:var(--blue);color:var(--blue)}
.page-btn.active{background:var(--blue);color:#fff;border-color:var(--blue)}
.page-btn.disabled{opacity:.4;cursor:default;pointer-events:none}
.page-ellipsis{color:var(--gray);font-size:13px;padding:0 4px}

/* MARKET SUMMARY */
.market-summary{background:var(--white);border-radius:var(--radius);border:1px solid var(--border);padding:24px;margin-top:24px}
.market-summary h3{font-size:16px;font-weight:700;margin-bottom:12px}
.market-summary p{font-size:13px;line-height:1.7;color:#3a3f47}
.market-summary strong{color:var(--navy)}
.summary-extra{display:none;margin-top:12px}
.summary-extra.open{display:block}
.read-more-btn{color:var(--blue);font-size:13px;font-weight:600;cursor:pointer;margin-top:10px;display:inline-flex;align-items:center;gap:4px;background:none;border:none;padding:0}
.read-more-btn:hover{text-decoration:underline}

/* INFO CONTENT */
.info-section{margin-top:24px;display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:20px}
.info-card{background:var(--white);border-radius:var(--radius);border:1px solid var(--border);padding:24px}
.info-card h4{font-size:15px;font-weight:700;margin-bottom:8px}
.info-card p{font-size:13px;line-height:1.7;color:var(--gray)}

/* FOOTER */
.footer{margin-top:40px;background:var(--white);border-top:1px solid var(--border);padding:40px 20px 24px}
.footer-inner{max-width:1400px;margin:0 auto}
.footer-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:32px;margin-bottom:32px}
.footer-col h5{font-size:13px;font-weight:700;margin-bottom:12px;color:var(--navy)}
.footer-col a{display:block;font-size:13px;color:var(--gray);padding:3px 0;transition:color .15s}
.footer-col a:hover{color:var(--blue);text-decoration:none}
.footer-bottom{border-top:1px solid var(--border);padding-top:20px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px}
.footer-copy{font-size:12px;color:var(--gray)}
.footer-social{display:flex;gap:12px}
.footer-social a{width:32px;height:32px;border-radius:50%;background:var(--gray-light);display:flex;align-items:center;justify-content:center;color:var(--gray);font-size:14px;transition:all .15s}
.footer-social a:hover{background:var(--blue);color:#fff}

/* RESPONSIVE */
@media(max-width:1024px){
  .nav{display:none}
  .header-inner{justify-content:space-between}
  .metrics-inner{gap:16px}
  .index-row{flex-wrap:wrap;gap:12px}
  .info-section{grid-template-columns:1fr}
}
@media(max-width:768px){
  .main{padding:12px}
  .promo-slide{font-size:12px}
  .ai-suggestions{gap:6px}
  .table-controls{flex-direction:column;align-items:flex-start}
  .footer-grid{grid-template-columns:repeat(2,1fr)}
}
@media(max-width:480px){
  .footer-grid{grid-template-columns:1fr}
  .header-inner{padding:0 12px}
  .metrics-inner{padding:8px 12px;gap:12px}
}

/* ANIMATIONS */
@keyframes fadeIn{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:translateY(0)}}
.table-wrapper tbody tr{animation:fadeIn .2s ease both}

/* RELATIVE POSITION HELPERS */
.relative{position:relative}
</style>
</head>
