const perPage = 100;

// ========== HELPERS ==========
function fmt(n) {
  if (n >= 1e12) return "$" + (n/1e12).toFixed(2) + "T";
  if (n >= 1e9) return "$" + (n/1e9).toFixed(2) + "B";
  if (n >= 1e6) return "$" + (n/1e6).toFixed(2) + "M";
  return "$" + n.toLocaleString("en-US");
}
function fmtPrice(p) {
  if (p >= 1) return "$" + p.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2});
  if (p >= 0.01) return "$" + p.toFixed(4);
  if (p >= 0.00001) return "$" + p.toFixed(6);
  return "$" + p.toFixed(8);
}
function fmtPct(v) {
  const s = v >= 0 ? "+" : "";
  return s + v.toFixed(2) + "%";
}
function pctClass(v) { return v >= 0 ? "up" : "down"; }

function sparkSVG(pts, positive) {
  const w = 120, h = 36, pad = 2;
  const mn = Math.min(...pts), mx = Math.max(...pts);
  const range = mx - mn || 1;
  const coords = pts.map((p, i) => {
    const x = pad + (i / (pts.length - 1)) * (w - 2*pad);
    const y = h - pad - ((p - mn) / range) * (h - 2*pad);
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  });
  const color = positive ? "#16C784" : "#EA3943";
  const gradId = "sg" + Math.random().toString(36).slice(2,8);
  return `<svg viewBox="0 0 ${w} ${h}" fill="none" xmlns="http://www.w3.org/2000/svg">
    <defs><linearGradient id="${gradId}" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="${color}" stop-opacity="0.2"/>
      <stop offset="100%" stop-color="${color}" stop-opacity="0"/>
    </linearGradient></defs>
    <path d="M${coords.join(" L")} L${w-pad},${h} L${pad},${h} Z" fill="url(#${gradId})"/>
    <polyline points="${coords.join(" ")}" stroke="${color}" stroke-width="1.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/>
  </svg>`;
}

function coinLogo(c) {
  const bg = c.color === "#000000" ? "#1a1a2e" : c.color;
  return `<div class="coin-logo" style="background:${bg}">${c.ticker.slice(0,2)}</div>`;
}

// ========== RENDER TABLE ==========
function getFilteredData() {
  let data = cryptoData.filter(c => c.cat.includes(activeCat));
  if (activeNet !== "all") data = data.filter(c => c.net.includes(activeNet));
  return data;
}

function renderTable() {
  const data = getFilteredData();
  const tbody = document.getElementById("tableBody");
  const start = (currentPage - 1) * perPage;
  const pageData = data.slice(start, start + perPage);

  if (pageData.length === 0) {
    tbody.innerHTML = `<tr><td colspan="11" style="text-align:center;padding:40px;color:var(--gray)">No cryptocurrencies found for this filter.</td></tr>`;
    renderPagination(0);
    return;
  }

  tbody.innerHTML = pageData.map((c, i) => {
    const isStarred = starred.has(c.ticker);
    return `<tr>
      <td class="star-col ${isStarred?"starred":""}" onclick="toggleStar('${c.ticker}')">&#9734;</td>
      <td class="rank">${c.r}</td>
      <td><div class="coin-info">${coinLogo(c)}<span class="coin-name">${c.name}<span class="coin-ticker">${c.ticker}</span></span></div></td>
      <td class="num" style="font-weight:600">${fmtPrice(c.price)}</td>
      <td class="pct ${pctClass(c.h1)} col-1h">${fmtPct(c.h1)}</td>
      <td class="pct ${pctClass(c.h24)} col-24h">${fmtPct(c.h24)}</td>
      <td class="pct ${pctClass(c.d7)} col-7d">${fmtPct(c.d7)}</td>
      <td class="num col-mcap">${fmt(c.mcap)}</td>
      <td class="num col-vol">${fmt(c.vol)}</td>
      <td class="num col-supply" style="color:var(--gray)">${c.supply}</td>
      <td class="col-spark"><div class="sparkline">${sparkSVG(c.spark, c.d7 >= 0)}</div></td>
    </tr>`;
  }).join("");

  renderPagination(data.length);
}

// ========== PAGINATION ==========
function renderPagination(total) {
  const totalPages = Math.ceil(total / perPage) || 1;
  const pag = document.getElementById("pagination");

  let pages = [];
  if (totalPages <= 7) {
    for (let i = 1; i <= totalPages; i++) pages.push(i);
  } else {
    pages = [1, 2, 3, 4, "...", totalPages - 1, totalPages];
  }

  const from = Math.min((currentPage - 1) * perPage + 1, total);
  const to = Math.min(currentPage * perPage, total);

  pag.innerHTML = `
    <span class="pagination-info">Showing ${from}–${to} of ${total.toLocaleString()} assets</span>
    <div class="pagination-pages">
      <button class="page-btn ${currentPage===1?"disabled":""}" onclick="goPage(${currentPage-1})">&#8249;</button>
      ${pages.map(p => typeof p === "number"
        ? `<button class="page-btn ${p===currentPage?"active":""}" onclick="goPage(${p})">${p}</button>`
        : `<span class="page-ellipsis">...</span>`
      ).join("")}
      <button class="page-btn ${currentPage===totalPages?"disabled":""}" onclick="goPage(${currentPage+1})">&#8250;</button>
    </div>
  `;
}

function goPage(p) {
  const total = getFilteredData().length;
  const totalPages = Math.ceil(total / perPage) || 1;
  if (p < 1 || p > totalPages) return;
  currentPage = p;
  renderTable();
  document.querySelector(".table-wrapper").scrollIntoView({behavior:"smooth",block:"start"});
}

// ========== TABS ==========
document.getElementById("categoryTabs").addEventListener("click", function(e) {
  const tab = e.target.closest(".tab");
  if (!tab) return;
  this.querySelectorAll(".tab").forEach(t => t.classList.remove("active"));
  tab.classList.add("active");
  activeCat = tab.dataset.cat;
  currentPage = 1;
  renderTable();
});

document.getElementById("networkTabs").addEventListener("click", function(e) {
  const tab = e.target.closest(".network-tab");
  if (!tab) return;
  this.querySelectorAll(".network-tab").forEach(t => t.classList.remove("active"));
  tab.classList.add("active");
  activeNet = tab.dataset.net;
  currentPage = 1;
  renderTable();
});

// ========== STAR / WATCHLIST ==========
function toggleStar(ticker) {
  if (starred.has(ticker)) starred.delete(ticker);
  else starred.add(ticker);
  renderTable();
}

// ========== SORTING ==========
document.getElementById("sortDropdown").addEventListener("change", function() {
  const key = this.value;
  const sortFn = {
    marketCap: (a,b) => b.mcap - a.mcap,
    volume: (a,b) => b.vol - a.vol,
    price: (a,b) => b.price - a.price,
    change24h: (a,b) => b.h24 - a.h24,
    change7d: (a,b) => b.d7 - a.d7
  }[key];
  if (sortFn) {
    cryptoData.sort(sortFn);
    cryptoData.forEach((c, i) => c.r = i + 1);
    currentPage = 1;
    renderTable();
  }
});

// ========== PANELS ==========
function togglePanel(id) {
  const panel = document.getElementById(id);
  const isOpen = panel.classList.contains("open");
  document.querySelectorAll(".dropdown-panel").forEach(p => p.classList.remove("open"));
  document.querySelectorAll(".control-btn").forEach(b => b.classList.remove("active"));
  if (!isOpen) {
    panel.classList.add("open");
    panel.previousElementSibling.classList.add("active");
  }
}

document.addEventListener("click", function(e) {
  if (!e.target.closest(".relative")) {
    document.querySelectorAll(".dropdown-panel").forEach(p => p.classList.remove("open"));
    document.querySelectorAll(".control-btn").forEach(b => b.classList.remove("active"));
  }
});

// ========== COLUMN TOGGLE ==========
function toggleColumn(cb) {
  const col = cb.dataset.col;
  const cells = document.querySelectorAll("." + col);
  cells.forEach(c => {
    if (cb.checked) c.classList.remove("col-hidden");
    else c.classList.add("col-hidden");
  });
}

// ========== MARKET SUMMARY ACCORDION ==========
function toggleSummary() {
  const extra = document.getElementById("summaryExtra");
  const arrow = document.getElementById("readMoreArrow");
  const btn = document.getElementById("readMoreBtn");
  const isOpen = extra.classList.contains("open");
  extra.classList.toggle("open");
  arrow.innerHTML = isOpen ? "&#9662;" : "&#9652;";
  btn.childNodes[0].textContent = isOpen ? "Read More " : "Show Less ";
}

